/* Play happens on the island: reveal a city, collect a word, open an easel. */
const playRoot=entity('a-entity',{id:'worldPlay'},scene),cityRoot=entity('a-entity',{position:'1.45 .12 -1.25'},playRoot),wordRoot=entity('a-entity',{position:'0 .7 .65'},playRoot),artRoot=entity('a-entity',{id:'islandArtBrush',position:'1.7 .025 -1.5',rotation:'0 0 0'},playRoot),wordCaption=entity('a-entity',{position:'-1.3 1.4 .1',visible:false},playRoot);
function playBox(parent,x,y,z,w,h,d,color){return entity('a-box',{position:`${x} ${y} ${z}`,width:w,height:h,depth:d,color},parent)}
cityRoot.object3D.userData.lensSubject='land';artRoot.object3D.userData.lensSubject='art';wordRoot.object3D.userData.lensSubject='art';
const hintRoot=entity('a-entity',{id:'playHint',visible:false},scene);
function makeInteractive(el,action,tip){el.classList.add('interactive');el.addEventListener('click',e=>{e.stopPropagation();action()});if(tip){el.addEventListener('mouseenter',()=>{status(tip);dispose(hintRoot);panel(hintRoot,{title:tip.split('·')[0].trim(),width:1.75,height:.25,font:45,align:'center'});const point=new THREE.Vector3();el.object3D.getWorldPosition(point);hintRoot.setAttribute('position',`${point.x} ${point.y+.38} ${point.z+.06}`);hintRoot.setAttribute('visible',true)});el.addEventListener('mouseleave',()=>hintRoot.setAttribute('visible',false))}}
function revealDestination(){cityRoot.replaceChildren();if(window.globiquest.renderHeritageMiniature?.(cityRoot,state.place))return;const index=state.place,c=['#e5ceb4','#c6b2c8','#9dc5be','#d4bc90'][index%4];entity('a-cylinder',{radius:.49,height:.07,position:'0 .035 0',color:'#e8e3d5'},cityRoot);const tower=(x,z,h,color=c)=>playBox(cityRoot,x,.08+h/2,z,.13,h,.13,color);if(index===0){for(let i=0;i<3;i++){tower(0,0,.45-i*.08,'#d8b695');entity('a-cone',{position:`0 ${.28+i*.21} 0`,'radius-bottom':.37-i*.06,'radius-top':.03,height:.11,color:'#77988f','segments-radial':8},cityRoot)}}else if(index===1){playBox(cityRoot,0,.27,0,.76,.35,.19,'#c2b196');for(const x of [-.32,.32])entity('a-cylinder',{position:`${x} .3 .015`,radius:.105,height:.48,color:'#b5a286','segments-radial':12},cityRoot);playBox(cityRoot,0,.22,.105,.14,.25,.018,'#796d5a');for(let i=0;i<7;i++)playBox(cityRoot,(i-3)*.105,.48,0,.056,.07,.19,'#c2b196')}else if(index===2){for(const x of [-1,1])for(const z of [-1,1]){const leg=playBox(cityRoot,x*.16,.36,z*.16,.055,.65,.055,'#b8aa93');leg.setAttribute('rotation',`${-z*15} 0 ${x*15}`)}playBox(cityRoot,0,.48,0,.4,.04,.4,'#b8aa93');tower(0,0,.92,'#b8aa93')}else if(index===3){for(let i=0;i<5;i++){const h=.5+Math.sin(i*.8)*.3;tower((i-2)*.13,0,h,'#b4c8b3');entity('a-cone',{position:`${(i-2)*.13} ${h+.14} 0`,'radius-bottom':.075,'radius-top':0,height:.18,color:i%2?'#d9b9bb':'#d9c69d'},cityRoot)}}else if(index===4){tower(-.2,0,.7,'#d0ad87');playBox(cityRoot,.17,.25,0,.4,.4,.2,'#dabd9b');entity('a-torus',{position:'.17 .27 .12',radius:.12,'radius-tubular':.028,'arc':180,color:'#f4e4cd'},cityRoot)}else if(index===5){playBox(cityRoot,0,.27,0,.76,.38,.38,'#a3b5a2');for(let i=0;i<4;i++)entity('a-dodecahedron',{position:`${-.35+i*.22} .19 .14`,radius:.2,color:'#9aaf9c'},cityRoot)}else if(index===6){for(let i=0;i<6;i++)tower((i%3-1)*.2,Math.floor(i/3)*.2,.35+(i%4)*.17,'#b0c1cd');tower(0,.1,1.04,'#b0c1cd')}else if(index===7||index===8){for(let i=0;i<4;i++)playBox(cityRoot,0,.07+i*.1,0,.72-i*.15,.1,.55-i*.1,index===7?'#cdb895':'#bdc3ae')}else if(index===9){for(let i=0;i<3;i++){playBox(cityRoot,(i-1)*.24,.28,0,.21,.46,.25,['#e7c7ad','#b5c9b4','#d3b8c6'][i]);playBox(cityRoot,(i-1)*.24,.28,.13,.08,.13,.02,'#7f9caa')}}else if(index===10){for(let i=0;i<4;i++)entity('a-cone',{position:`${(i-1.5)*.2} ${.27+i*.045} 0`,scale:'1 1 .55','radius-bottom':.18,'radius-top':0,height:.45+i*.08,color:'#f5eee2','segments-radial':3,rotation:`0 ${i*12} ${-15+i*7}`},cityRoot)}else{for(let i=0;i<3;i++)entity('a-cone',{position:`${(i-1)*.22} .35 0`,'radius-bottom':.3,'radius-top':0,height:.6+i*.09,color:i%2?'#cbd8ce':'#aebfb5','segments-radial':5},cityRoot)}cityRoot.setAttribute('animation__rise','property:scale; from:.05 .05 .05; to:1 1 1; dur:850; easing:easeOutBack')}
entity('a-cylinder',{radius:.13,height:.12,color:'#dcebe5',position:'0 .06 0',material:'roughness:.85'},artRoot);entity('a-torus',{radius:.13,'radius-tubular':.014,rotation:'90 0 0',position:'0 .12 0',color:'#f5f7ee'},artRoot);const brush=entity('a-cylinder',{radius:.035,height:.5,color:'#ede5d8',position:'0 .2 0'},artRoot);const tip=entity('a-cone',{'radius-bottom':.06,'radius-top':0,height:.19,color:'#a48fb3',position:'0 .55 0'},artRoot);entity('a-cylinder',{radius:.047,height:.1,color:'#d9bd83',position:'0 .43 0'},artRoot);[brush,tip].forEach(el=>makeInteractive(el,()=>openAdventure('art'),'Artist’s brush · open the easel on the island'));
function celebrate(count=24){const colors=['#f6ce7c','#b5dfca','#e3bad2','#b3d6ee'];for(let i=0;i<count;i++){const x=(Math.random()-.5)*2.5,y=1.1+Math.random()*.7,z=-.8+Math.random();const spark=entity('a-sphere',{radius:.018+Math.random()*.018,position:`${x} ${y} ${z}`,material:`shader:flat; color:${colors[i%4]}; transparent:true; opacity:.9`,'segments-width':5,'segments-height':4,animation:`property:position; to:${x*1.6} ${y+1+Math.random()} ${z+.6}; dur:1600; easing:easeOutQuad`,'animation__fade':'property:material.opacity; to:0; dur:1600; easing:linear'},playRoot);setTimeout(()=>spark.remove(),1700)}}
const hiddenPostcards=new Set();try{const stored=JSON.parse(localStorage.getItem('globiquest.hidden-postcards')||'[]');if(Array.isArray(stored))stored.filter(r=>regions.includes(r)).forEach(r=>hiddenPostcards.add(r))}catch{}
const postcardControl=document.createElement('button');postcardControl.innerHTML='<span>×</span>Clear postcard';postcardControl.setAttribute('aria-label','Clear postcard from the island');postcardControl.style.display='none';document.getElementById('spatialDock').append(postcardControl);
function savePostcardVisibility(){try{localStorage.setItem('globiquest.hidden-postcards',JSON.stringify([...hiddenPostcards]))}catch{}}
function showPostcard(){const old=$('islandPostcard');if(old)old.remove();const region=regions[state.region],art=adventure.art(region),visible=!!art&&!hiddenPostcards.has(region);postcardControl.style.display=visible?'':'none';if(!visible)return;const frame=entity('a-entity',{id:'islandPostcard',position:'-1.8 .7 -.9',rotation:'0 12 0'},playRoot);playBox(frame,0,0,-.02,.78,.53,.04,'#d6c3a3');const image=entity('a-plane',{width:.7,height:.44,src:art.data,position:'0 0 .012',material:'shader:flat; side:double'},frame);image.classList.add('interactive');image.addEventListener('click',()=>{gallerySelection=region;openAdventure('memory')});panel(frame,{title:'Clear',width:.27,height:.11,x:.23,y:.2,z:.04,font:70,align:'center',action:()=>window.globiquest.clearPostcard()})}
window.globiquest.clearPostcard=()=>{hiddenPostcards.add(regions[state.region]);savePostcardVisibility();const old=$('islandPostcard');if(old)old.remove();postcardControl.style.display='none';status('Postcard cleared from the island. Your gallery copy is kept.')};postcardControl.onclick=()=>window.globiquest.clearPostcard();
window.globiquest.displayPostcard=(region=regions[state.region])=>{hiddenPostcards.delete(region);savePostcardVisibility();if(region!==regions[state.region])chooseRegion(regions.indexOf(region));showPostcard()};

window.globiquest.celebrate=celebrate;window.globiquest.showPostcard=showPostcard;window.globiquest.revealDestination=()=>{revealDestination();showPostcard()};window.globiquest.refreshPlayLayout=(x,compact)=>{playRoot.setAttribute('position',`${x} ${compact?.65:.7} ${compact?-.63:-.25}`);playRoot.setAttribute('scale',compact?'.65 .65 .65':'.86 .86 .86')};window.globiquest.revealDestination();window.globiquest.refreshWorkspace();
